import os

from selenium.common.exceptions import TimeoutException
from taf.selenium.core.exceptions import TooManyFilesFoundException

from taf.rfrl.procedures.resources.python.logger.logger import log_input_and_output, log_result
from taf.rfrl.procedures.resources.python.exceptions import (
    RfScanShouldNotBeAvailable,
    RfScanFileNotFoundOrWrongFileName,
    RfScanFileSizeNotCorrect,
    RadioNameNotFoundInProvidedDictionary,
)
from taf.rfrl.procedures.resources.python.vm import get_file_size, move_file_to_target_directory
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import (
    get_rmod_details_with_rf_sw,
    get_cell_ids_for_ru_from_specific_rats,
    get_cell_technology,
    get_admin_cells_parameters,
)


@log_input_and_output
def prepare_rf_scan_input_data(connection, radio_supported_capture_types):
    """
    Prepares the entry data for RF Scanning procedure. For every radio a dictionaries are created with capture type,
    technology, local cell id, antenna, antenna panel info. Values for keys: 'radio', 'technology', 'local_cell',
    'antenna',  'antenna panel' are taken from admin bts info. Values for key: 'capture_type' are taken from
    radio_supported_capture_types. For mmimo radios value of antenna_panel always contains only Full Array option.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param radio_supported_capture_types: dictionary with capture types for every radio used in configuration.
           e.g.: {'AEHC': ['Carrier Rx (FIR9)', 'Raw Composite Rx (RxADC)'],
                  'AHPE': ['Carrier Rx (FIR9)', 'Composite Rx (HBF0)']}
    :type radio_supported_capture_types: dict
    :return: list of dictionaries with every possible combination of required parameters for RF Scan procedure.
    :rtype: list of dicts
    """
    rmods_details = get_rmod_details_with_rf_sw(connection)
    cells_parameters = get_admin_cells_parameters(connection)

    cells_rx_carriers = _get_rx_carriers_per_cell(cells_parameters)

    rf_scan_input_data = _get_basic_rmod_details(rmods_details)
    rf_scan_input_data = _add_capture_type(rf_scan_input_data, radio_supported_capture_types)
    rf_scan_input_data = _add_cells_details(rf_scan_input_data, connection)
    rf_scan_input_data = _add_antenna_and_panel_info(rf_scan_input_data, cells_rx_carriers)
    rf_scan_input_data = _remove_local_cell_for_specific_capture_type(rf_scan_input_data)

    return rf_scan_input_data


@log_input_and_output
def verify_rf_scan_unavailability(rf_scan_parameters_dict, webui_obj):
    """
    Verifies if starting RF scanning procedure is not available and raises an exception if is.

    :param rf_scan_parameters_dict: dictionary with 'technology', 'radio', 'capture_type', 'antenna', 'antenna_panel',
    'local_cell', 'download_timeout'(optional), 'timeout'(optional) keys.
    :type rf_scan_parameters_dict: dict
    :param webui_obj: webui instance
    :type webui_obj: webui
    :raises RfScanShouldNotBeAvailable: if RF Scan is available when should not be
    """
    if _is_rf_scan_available(rf_scan_parameters_dict, webui_obj):
        raise RfScanShouldNotBeAvailable('RF scanning procedure should not be available.')
    else:
        log_result('RF Scanning procedure in not available.')


@log_input_and_output
def verify_rf_scan_result_file(rf_scan_path, rf_scan_path_download):
    """
    Verifies if the collected RF Scan result file is correct:
        1) RF Scan result file name should match a pattern.
        2) RF Scan result file size should be bigger than zero.
    RF Scan result file name should start with 'RFMonitoring'.

    :param rf_scan_path: path to verified RF Scan files
    :type rf_scan_path: str
    :param rf_scan_path_download: path to downloaded RF Scan files
    :type rf_scan_path_download: str
    :raises RfScanFileSizeNotCorrect: if RF Scan file size is not bigger than zero
    """
    rf_scan_file_name = _get_name_of_rf_scan_file_in_given_dir_and_check_starting_characters(rf_scan_path_download)
    rf_scan_file_size = get_file_size(rf_scan_path_download + '/' + rf_scan_file_name)
    move_file_to_target_directory(rf_scan_path_download + '/' + rf_scan_file_name, rf_scan_path + '/'
                                  + rf_scan_file_name)

    if rf_scan_file_size > 0:
        log_result('File name and size for file: {} are correct.'.format(rf_scan_file_name))
    else:
        raise RfScanFileSizeNotCorrect('RF Scan file size: {} not bigger than zero for {} file.'.format(
            rf_scan_file_size, rf_scan_file_name))


@log_input_and_output
def _is_rf_scan_available(rf_scan_parameters_dict, webui_obj):
    """
    Checks if starting RF scanning procedure is available by verifying if expected exception was raised during starting
    RF scan.

    :param rf_scan_parameters_dict: dictionary with 'technology', 'radio', 'capture_type', 'antenna', 'antenna_panel',
    'local_cell', 'download_timeout'(optional), 'timeout'(optional) keys.
    :type rf_scan_parameters_dict: dict
    :param webui_obj: webui instance
    :type webui_obj: webui
    :return: True if available, False if not
    :rtype: bool
    """
    try:
        webui_obj.start_rf_scan(**rf_scan_parameters_dict)
    except TimeoutException:
        return False
    except TooManyFilesFoundException:
        return True
    else:
        return True


@log_input_and_output
def _get_name_of_rf_scan_file_in_given_dir_and_check_starting_characters(rf_scan_dir):
    """
    Gets name of RF Scan result file from rf_scan_dir directory

    :return: name of RF Scan result file
    :rtype: str
    """
    for file_name in os.listdir(rf_scan_dir):
        if file_name.startswith('RFMonitoring'):
            return file_name

    raise RfScanFileNotFoundOrWrongFileName('RF Scan file not found in {} or wrong file name '
                                            '(Should starts with "RFMonitoring").'.format(rf_scan_dir))


@log_input_and_output
def _get_rx_carriers_per_cell(cells_parameters):
    """
    Gets RX carrier sets for every cell in admin bts info.

    :param cells_parameters: list of parameters of cells from admin bts info
    :type cells_parameters: list of dicts
    :return: dict with RX carriers for every cell  e.g. {'NRCELL-1': {'PHYANT-1'}, 'LNCEL-2': {'ANTL-2', 'ANTL-4'}}
    :rtype: dict
    """
    rx_carriers = {}
    for cell_parameters in cells_parameters:
        rx_carriers[cell_parameters['configurationDistName'].split('/')[-1]] = {
            carrier['antennaLineId']['configuration'].split('/')[-1] for carrier in cell_parameters[
                'carrierList'] if carrier['direction'] == 'RX'
        }
    return rx_carriers


@log_input_and_output
def _get_basic_rmod_details(rmods_details):
    """
    Gets basic rmods' details - rmod id and formatted radio's name for RF Scan.

    :param rmods_details: list of dictionaries with rmods' details including rmod_id and product_name
    :type rmods_details: list of dicts
    :return: list of dictionaries with basic rmod info (id, formatted name)
             e.g. [{'rmod_id': '2', 'radio': 'RMOD-2 (AHPE)'}, {'rmod_id': '1', 'radio': 'RMOD-1 (AEHC)'}]
    :rtype: list of dicts
    """
    basic_rmod_detail = [{'rmod_id': rmod['rmod_id'],
                          'radio': 'RMOD-{} ({})'.format(rmod['rmod_id'], rmod['product_name'])}
                         for rmod in rmods_details]
    return basic_rmod_detail


@log_input_and_output
def _add_capture_type(rmods_details, radio_supported_capture_types):
    """
    Adds to dictionaries with input data for RF Scanning procedure info about capture type.
    Available capture types for every rmod are in radio_supported_capture_types.

    :param rmods_details: list of dictionaries with basic rmod info (id, formatted name)
    :type rmods_details: list of dicts
    :param radio_supported_capture_types: dictionary with capture types for every radio used in configuration.
           e.g.: {'AEHC': ['Carrier Rx (FIR9)', 'Raw Composite Rx (RxADC)'],
                  'AHPE': ['Carrier Rx (FIR9)', 'Composite Rx (HBF0)']}
    :type radio_supported_capture_types: dict
    :return: list of dictionaries with rmod info (id, formatted name) and capture type
             e.g. [{'rmod_id': '2', 'radio': 'RMOD-2 (AHPE)', 'capture_type': 'Carrier Rx (FIR9)'},
                   {'rmod_id': '2', 'radio': 'RMOD-2 (AHPE)', 'capture_type': 'Composite Rx (HBF0)'},
                   {'rmod_id': '1', 'radio': 'RMOD-1 (AEHC)', 'capture_type': 'Carrier Rx (FIR9)'},
                   {'rmod_id': '1', 'radio': 'RMOD-1 (AEHC)', 'capture_type': 'Raw Composite Rx (RxADC)'}]
    :rtype: list of dicts
    """
    rmod_details_with_capture_type = []
    for rmod in rmods_details:
        radio_name = rmod['radio'][rmod['radio'].find('(') + 1:rmod['radio'].find(')')]
        if radio_name not in radio_supported_capture_types.keys():
            raise RadioNameNotFoundInProvidedDictionary(
                'Radio {} not found in radio_supported_capture_types dictionary.'.format(radio_name))
        for capture_type in radio_supported_capture_types[radio_name]:
            new_entry = rmod.copy()
            new_entry['capture_type'] = capture_type
            rmod_details_with_capture_type.append(new_entry)

    return rmod_details_with_capture_type


@log_input_and_output
def _add_cells_details(rmods_details, connection):
    """
    Adds to dictionaries with input data for RF Scanning procedure info about cell name and technology.

    :param rmods_details: list of dictionaries with basic rmod info (id, formatted name, capture type)
    :type rmods_details: list of dicts
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: list of dictionaries with rmod info (id, formatted name), capture type, technology and cell name
             e.g. [{'rmod_id': '2', 'radio': 'RMOD-2 (AHPE)', 'capture_type': 'Carrier Rx (FIR9)',
                    'technology': 'LTE FDD', 'local_cell': 'LNCEL-2'},
                   {'rmod_id': '2', 'radio': 'RMOD-2 (AHPE)', 'capture_type': 'Composite Rx (HBF0)',
                    'technology': 'LTE FDD', 'local_cell': 'LNCEL-2'}]
    :rtype: list of dicts
    """
    entry_data_rmod_cells_technology = []
    for rmod in rmods_details:
        cells = get_cell_ids_for_ru_from_specific_rats(connection, rmod['rmod_id'], ["lte", "nr"])
        for cell in cells['lte']:
            new_entry = rmod.copy()
            new_entry['technology'] = 'LTE {}'.format(get_cell_technology(connection, 'lte', cell))
            new_entry['local_cell'] = 'LNCEL-{}'.format(cell)
            entry_data_rmod_cells_technology.append(new_entry)
        for cell in cells['nr']:
            new_entry = rmod.copy()
            new_entry['technology'] = 'NR {}'.format(get_cell_technology(connection, 'nr', cell))
            new_entry['local_cell'] = 'NRCELL-{}'.format(cell)
            entry_data_rmod_cells_technology.append(new_entry)
    return entry_data_rmod_cells_technology


@log_input_and_output
def _add_antenna_and_panel_info(rf_scan_input_data, cells_rx_carriers):
    """
    Adds to dictionaries with input data for RF Scanning procedure info about antenna and antenna panel.
    For mmimo rmods antenna panel in not None and has always only Full Array option.
    Rmod's ids are removed from input data.

    :param rf_scan_input_data: list of dictionaries with input data for RF Scanning procedure
    :type rf_scan_input_data: list of dicts
    :param cells_rx_carriers: dict with RX carriers for every cell
    :type cells_rx_carriers: dict
    :return: list of dictionaries with rmod formatted name, capture type, technology, cell name, antenna, antenna panel.
             e.g. [{'radio': 'RMOD-2 (AHPE)', 'capture_type': 'Carrier Rx (FIR9)', 'technology': 'LTE FDD',
                    'local_cell': 'LNCEL-2', 'antenna_panel': None, 'antenna': 'ANT 4'},
                   {'radio': 'RMOD-2 (AHPE)', 'capture_type': 'Carrier Rx (FIR9)', 'technology': 'LTE FDD',
                    'local_cell': 'LNCEL-2', 'antenna_panel': None, 'antenna': 'ANT 2'}]

    :rtype: list of dicts
    """
    complete_input_data = []
    for rf_scan_entry in rf_scan_input_data:
        for cell_rx_carrier in cells_rx_carriers[rf_scan_entry['local_cell']]:
            new_entry = rf_scan_entry.copy()
            new_entry.pop('rmod_id')
            if 'L-' in cell_rx_carrier:
                new_entry['antenna_panel'] = None
                new_entry['antenna'] = cell_rx_carrier.replace('L-', ' ')
            else:
                new_entry['antenna_panel'] = '{} Full Array'.format(cell_rx_carrier)
                new_entry['antenna'] = cell_rx_carrier.replace('-', ' ')
            complete_input_data.append(new_entry)
    return complete_input_data


@log_input_and_output
def _remove_local_cell_for_specific_capture_type(rf_scan_input_data):
    """
    Removes local cell from dictionaries with input data for RF Scanning procedure with capture type not equals to
    'Carrier Rx (FIR9)'.

    :param rf_scan_input_data: list of dictionaries with input data for RF Scanning procedure
    :type rf_scan_input_data: list of dicts
    :return: list of dictionaries with rmod formatted name, capture type, technology, cell name, antenna, antenna panel.
             e.g. [{'radio': 'RMOD-2 (AHPE)', 'capture_type': 'Carrier Rx (FIR9)', 'technology': 'LTE FDD',
                    'local_cell': 'LNCEL-2', 'antenna_panel': None, 'antenna': 'ANT 4'},
                   {'radio': 'RMOD-2 (AHPE)', 'capture_type': 'Composite Rx (HBF0)', 'technology': 'LTE FDD',
                    'local_cell': None, 'antenna_panel': None, 'antenna': 'ANT 4'}]
    :rtype: list of dicts
    """
    for rf_scan_entry in rf_scan_input_data:
        if rf_scan_entry['capture_type'] != 'Carrier Rx (FIR9)':
            rf_scan_entry['local_cell'] = None
    return rf_scan_input_data
